<?php declare(strict_types=1); namespace App\Models; use App\Enums\EventCompetitionEntryStatus; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; final class EventCompetitionEntry extends Model { protected $table='forum_event_competition_entries'; protected $guarded=[]; protected function casts():array{return ['status'=>EventCompetitionEntryStatus::class,'eligibility_snapshot'=>'encrypted:array','rules_accepted_at'=>'immutable_datetime','withdrawn_at'=>'immutable_datetime','disqualified_at'=>'immutable_datetime'];} public function competition():BelongsTo{return $this->belongsTo(EventCompetition::class,'competition_id');} public function registration():BelongsTo{return $this->belongsTo(ForumEventRegistration::class,'forum_event_registration_id');} public function pets():HasMany{return $this->hasMany(EventCompetitionEntryPet::class,'entry_id');} }
